  "name": "The Night Court",
  "aka": [],
  "tag": "institution",
  "facts": [
    {
      "category": "general",
      "text": "The Night Court is the primary instrument of governance in the Tsardom of Moscavia, conducting all legislative and administrative work after sundown as mandated by the Night Court Decree of 995.",
      "since": "995"
    },
    {
      "category": "general",
      "text": "The Night Court governs the Tsardom exclusively after sundown, with sessions lasting through the early morning hours and decisions announced at dawn to the waking human population."
    },
    {
      "category": "general",
      "text": "Tsar Dmitry IV presides over the Night Court from his palace in Velikoye and holds ultimate authority over all matters of state."
    },
    {
      "category": "general",
      "text": "Tsar Dmitry IV issued the Night Court Decree, mandating that all governance would take place after sundown to accommodate the Owl-folk's nocturnal nature."
    },
    {
      "category": "general",
      "text": "All public buildings in the Tsardom must display roosting perches and talon-gripping ledges at every window by decree of the Night Court, transforming the architecture of the realm to suit Owl-folk inhabitants."
    },
    {
      "category": "general",
      "text": "Non-Owl-folk merchants must conduct business during twilight hours to align with the Night Court's operating schedule, a policy enacted to accommodate the Tsardom's ruling class."
    },
    {
      "category": "general",
      "text": "The Night Court was established in response to the Blinding of 994, which transformed millions of humans into Owl-folk and necessitated a restructuring of governance to suit the nocturnal habits of the transformed population."
    },
    {
      "category": "general",
      "text": "Debates within the Night Court are conducted through vocalization supplemented by Plumage Signaling, in which subtle shifts in feather coloration and arrangement convey agreement, disagreement, or urgency among advisors."
    },
    {
      "category": "general",
      "text": "The Night Court operates out of a grand stone chamber within the Tsar's palace in Velikoye, its halls lit by enchanted moonstone lanterns that cast a pale, steady glow across the assembled advisors and clerks."
    },
    {
      "category": "general",
      "text": "A Senior Advisor who ruffles the feathers along the lower neck while keeping the wings pressed flat is signaling formal objection to a motion under discussion, a gesture recognized as carrying the weight of a spoken veto."
    },
    {
      "category": "general",
      "text": "The Night Court's sessions are attended by Owl-folk advisors, military commanders of the Frostwing Host, and representatives of the Order of the Talon-Scribe, who provide counsel on magical and runic matters."
    }
  ],
