  "name": "Vasha",  
  "age": 5,  
  "aka": [],  
  "tag": "courier",  
  "facts": [  
    {  
      "category": "appearance",  
      "text": "Vasha is a Snowy Owl-folk in her natural form — a young snowy owl of five years, with pristine white plumage and faint grey barring visible only when the light catches her feathers at certain angles."  
    },  
    {  
      "category": "appearance",  
      "text": "Her eyes are a striking pale amber, round and bright, with a piercing quality that belies her youth."  
    },  
    {  
      "category": "appearance",  
      "text": "Her talons are notably large for her size, strong enough to grip a rolled letter tube firmly mid-flight without risk of dropping it."  
    },  
    {  
      "category": "background",  
      "text": "Vasha was born entirely in owl form in the year 996, making her one of the first generation of Snowy Owl-folk who never experienced human life."  
    },  
    {  
      "category": "background",  
      "text": "She was born in Velikoye to a postal family — her mother, a human-turned-Snowy Owl-folk named Yelena, had served as a letter courier before the transformation and continued in the role afterward."  
    },  
    {  
      "category": "background",  
      "text": "Her mother Yelena died of a winter fever in the year 999, leaving Vasha in the care of the Northern Postal Authority's courier dormitory in Velikoye."  
    },  
    {  
      "category": "background",  
      "text": "Vasha entered the Northern Postal Authority's junior courier program at the age of three, the youngest age permitted under Postal Authority regulations."  
    },  
    {  
      "category": "ability",  
      "text": "She is a competent flyer for her age, capable of covering the roughly thirty miles between Velikoye and the northern town of Murmashi in under two hours with a light letter load."  
    },  
    {  
      "category": "personality",  
      "text": "Vasha is serious-minded and quietly determined, a trait her handlers attribute to having grown up in the structured environment of the postal dormitory rather than a family household."  
    },  
    {  
      "category": "personality",  
      "text": "She takes pride in the speed and accuracy of her deliveries, though she is also prone to nervous preening when she encounters unfamiliar situations."  
    },  
    {  
      "category": "relationship",  
      "text": "Her direct supervisor within the Northern Postal Authority is a veteran Eared Owl-folk courier named Aleksei, who serves as her route coordinator and field instructor."  
    }  
  ],  
