 "entries": [
    {
        "name": "The Khorol Ice-Road Pilots' Brotherhood",
        "kind": "lore",
        "tag": "guild",
        "line": "Founded in 997 by order of Tsar Dmitry IV, the Khorol Ice-Road Pilots' Brotherhood is the sanctioned guild of licensed ice-road navigators who guide trade caravans, military convoys, and civilian travelers across the frozen surface of the Khorol River and its tributary routes during the long northern winter, operating out of timber-framed waystations along the river's banks in and around Velikoye."
    },
    {
        "name": "The Shivering Lantern Company",
        "kind": "lore",
        "tag": "guild",
        "line": "A private trade guild established in the year 1000 by the merchant-owl Vesper Khramova, the Shivering Lantern Company specializes in chartering frozen Khorol routes for luxury goods and Owl-folk commerce, maintaining a fleet of reinforced sledges and employing Brotherhood-trained pilots to run high-value trade between Velikoye and the northern provinces."
    }
] }

 "entries": [
    {
        "name": "Viktor Semyonov",
        "kind": "character",
        "tag": "official",
        "line": "Viktor Semyonov is the First Deputy to the Chief Scribe, a tall, lean eared Owl-folk with tawny breast feathers and a wingspan exceeding nine feet, who serves as the Order's senior administrator and oversees day-to-day operations at the Academy of the Chiseled Moon, managing correspondence with provincial rune-stations across the Tsardom."
    },
    {
        "name": "Elena Vashchenko",
        "kind": "character",
        "tag": "official",
        "line": "Elena Vashchenko is the Second Deputy to the Chief Scribe, a broad-shouldered burrowing Owl-folk standing just over four feet tall with mottled grey-brown plumage, who leads the Corrupted Rune Site Investigation branch and reports directly to Chief Scribe Koroleva on matters of rune decay, sabotage, and magical contamination affecting public inscriptions throughout the Tsardom."
    }
] }


  "name": "The Academy of the Chiseled Moon",
  "aka": [
    {
      "name": "The Rune Academy",
      "tag": "common",
      "everyday": true
    }
  ],
  "tag": "institution",
  "facts": [
    {
      "category": "description",
      "text": "The central administrative seat of the Order of the Talon-Scribe, housed in a stone hall in the inner quarter of Velikoye.",
      "since": null,
      "held_by": null
    },
    {
      "category": "description",
      "text": "The building is carved from pale grey granite quarried from the Khorol River bluffs, its façade dominated by the carved motto 'By Talon and Stone, the Land Endures' above the main entrance.",
      "since": null,
      "held_by": null
    },
    {
      "category": "description",
      "text": "Inside, the halls are organized around a central courtyard where Novice scribes practice on designated training stones, their chiseling audible from the corridors at all hours of the night.",
      "since": null,
      "held_by": null
    },
    {
      "category": "description",
      "text": "The eastern wing contains the Grand Chiseling Hall, a long vaulted chamber where senior scribes carve the master copies of approved rune patterns that are then replicated across the Tsardom.",
      "since": null,
      "held_by": null
    },
    {
      "category": "description",
      "text": "The western wing holds the Archive of Approved Patterns, a vast collection of stone tablets storing copies of every rune design currently sanctioned for public use, organized by function and province of origin.",
      "since": null,
      "held_by": null
    },
    {
      "category": "description",
      "text": "The upper floors contain roosting alcoves and sleeping chambers for the Academy's resident scribes, Novices, and the Chief Scribe, all fitted with wide windowsills and talon-gripping ledges as mandated by Night Court decree for all public buildings in Velikoye.",
      "since": null,
      "held_by": null
    },
    {
      "category": "history",
      "text": "The Academy was established under Tsar Dmitry IV's Scribing Decree of 998, which formalized the Order of the Talon-Scribe and mandated a permanent central institution to oversee rune-working across the Tsardom.",
      "since": 998,
      "held_by": null
    },
    {
      "category": "history",
      "text": "Before the Blinding of 994, the site served as the Velikoye Rune Academy, a training school for human practitioners that had operated for over a century, though it lacked the formal state authority the current institution holds.",
      "since": null,
      "held_by": null
    },
    {
      "category": "history",
      "text": "Chief Scribe Anastasiya Koroleva was already a practicing scribe at this location when the Blinding transformed her, and she remained seated at her carving desk in the eastern wing as the transformation took hold, her half-finished mold still wet in its frame.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "law",
      "text": "All Novice scribes enrolled in Order training are required to spend three years in apprenticeship at the Academy before they may carve any rune intended for public display.",
      "since": 998,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Academy serves as the headquarters from which the Chief Scribe declares rune sites corrupted or dormant, dispatches investigation teams, and oversees the maintenance of Tier-One Public Sites such as the Frostmere Runic Array.",
      "since": 997,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The institution also coordinates the annual Rune Census each spring, dispatching registered scribes across every province of the Tsardom to survey all public inscriptions for wear, corruption, or magical interference.",
      "since": 998,
      "held_by": null
    }
  ],
