    {
      "entry": "Khorol River",
      "text": "The frozen surface of the Khorol serves as a patrol corridor for the Frostwing Host, whose nighttime flights provide continuous surveillance of Velikoye's riverbank defenses during the eight-month winter freeze."
    },
    {
      "entry": "Khorol River",
      "text": "The Khorol forms a natural moat around Velikoye's fortifications, making the capital exceptionally difficult to approach by land during winter without crossing the ice under the watchful eyes of the Frostwing Host."
    },
    {
      "entry": "Tsardom of Moscavia",
      "text": "The Frostwing Host, an all-Owl-folk military force, serves as the primary military arm of the Tsardom and reflects the fundamental transformation of the realm's population since the Blinding of 994."
    },
    {
      "entry": "Velikoye",
      "text": "The watchtowers of Velikoye, originally built to defend against steppe raiding parties, now function as roosting stations for the Frostwing Host, which conducts silent nocturnal patrols across the capital's rooftops and riverbanks."
    },
    {
      "entry": "The White Talon",
      "text": "The White Talon operates as a heavy regiment within the broader Frostwing Host, flying at the head of the Host's mass formation during the Winter Solstice Vigil and standing permanent guard over the Tsar's Palace and the walls of Velikoye."
    },
    {
      "entry": "Winter Solstice Vigil",
      "text": "The Frostwing Host performs its most spectacular public display during the Winter Solstice Vigil, executing a ceremonial mass flight over Velikoye that draws tens of thousands of spectators to the frozen banks of the Khorol."
    },
    {
      "entry": "The Blinding",
      "text": "The Blinding of 994 precipitated the creation of the Frostwing Host three years later, as the Night Court recognized the need for a military force composed entirely of the Owl-folk who now constituted the vast majority of the Tsardom's fighting-age population."
    },
    {
      "entry": "Tsar Dmitry IV",
      "text": "Tsar Dmitry IV, who underwent the transformation of the Blinding and continued to rule as an Owl-folk, presides over the Tsardom and its military, including the Frostwing Host which defends the frozen capital of Velikoye."
    }
  ]
}

{ "name": "Ice-Road Pilots' Guild",
  "aka": [
    {
      "name": "Pilots' Guild",
      "tag": "common",
      "everyday": true
    }
  ],
  "tag": "institution",
  "facts": [
    {
      "category": "general",
      "text": "The Ice-Road Pilots' Guild is the licensed body of skilled navigators who guide sledge caravans and barges along the Khorol River, whether frozen or thawed.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Founded in the year 997, three years after the Blinding transformed the Tsardom's populace and disrupted long-established trade networks, the Guild was chartered by decree of Tsar Dmitry IV to restore and regulate commerce along the Khorol's ice road and summer waterway.",
      "since": "997",
      "held_by": null
    },
    {
      "category": "general",
      "text": "Membership requires a candidate to submit to a rigorous examination covering ice-thickness assessment, current mapping, seasonal weather patterns, knowledge of the Frostmere Glaciers' influence on river conditions, and emergency protocols for river crossings and thin-ice encounters.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Certified Pilots carry a guild-issued bronze compass marked with the Khorol Mouth Stones' rune-symbols, which serves both as a navigation tool and proof of licensure.",
      "since": "997",
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Guild's headquarters stands on the south bank of the Khorol in Velikoye, in a timber-and-stone hall near the Riverward Market, its facade carved with a bas-relief map of the river's full length from the Frostmere Glaciers to the Greensea Strait.",
      "since": "997",
      "held_by": null
    },
    {
      "category": "general",
      "text": "During the frozen months, Pilots lead caravans of loaded sledges northward into the boreal forests and glacier foothills, charting routes across the ice that must account for pressure ridges, snowdrift accumulation, and the Frostwing Host's patrol corridors.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "In summer, the same Pilots transition to guiding barges through the Khorol's shallow and rocky stretches, reading the water's currents and shallows that have shifted since the last thaw.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Guild maintains a network of marker posts along the Khorol's length, each one bearing a colored flag and a logbook where Pilots record ice conditions, debris locations, and passage times, enabling subsequent caravans to travel with greater safety.",
      "since": "997",
      "held_by": null
    },
    {
      "category": "general",
      "text": "Guild Pilots are trained to communicate using lantern signals at night and whistle codes during daytime travel, allowing caravans to relay warnings about ice fractures, approaching storms, or bandit activity across distances of several miles.",
      "since": "997",
      "held_by": null
    },
    {
      "category": "general",
      "text": "Any Pilot who loses a sledge or its cargo through negligence faces suspension and a fine equal to the value of the lost goods, as adjudicated by the Night Court's trade division; repeat offenders may be stripped of their license permanently.",
      "since": "997",
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Guild's annual festival, held during the Winter Solstice Vigil, includes a ceremony in which newly certified Pilots receive their bronze compasses and swear an oath to prioritize the safety of their caravan above personal gain.",
      "since": "998",
      "held_by": null
    }
  ],
