p4.reply:
{ "name": "Valdren",
  "aka": [
    {"name": "The Kingdom of Valdren", "tag": "proper", "everyday": false}
  ],
  "tag": "kingdom",
  "facts": [
    {"category": "description", "text": "Valdren is a mountainous kingdom to the west of the Tsardom of Moscavia, separated by the Greenwall Mountains that run along the border.", "since": null, "held_by": null},
    {"category": "general", "text": "The kingdom's interior is dominated by deep valleys, alpine meadows, and dense coniferous forests at lower elevations, giving way to barren stone peaks near the summit ridges of the Greenwall.", "held_by": null},
    {"category": "general", "text": "Valdren's primary settlements cluster in the broad river valleys that cut through the western foothills, where glacial meltwater from the Greenwall feeds fertile farmland and supports modest but productive agriculture.", "held_by": null},
    {"category": "general", "text": "The kingdom maintains a network of mountain passes through the Greenwall, some of which remain open year-round while others close during the harshest winter months, making border traffic seasonal and unpredictable.", "held_by": null},
    {"category": "history", "text": "Valdren has maintained an uneasy diplomatic relationship with Moscavia since before the Blinding, with trade disputes over timber, grain, and mineral rights periodically straining relations between the two realms.", "held_by": null},
    {"category": "law", "text": "Valdren has not undergone a transformation event like the Blinding, and its population remains entirely human, which has created significant cultural and political tension with the transformed Moscavian state to its east.", "held_by": null},
    {"category": "general", "text": "The kingdom's military, while smaller than Moscavia's Frostwing Host, relies on mountain infantry trained to navigate the treacherous terrain of the Greenwall passes, making direct invasion of either realm impractical.", "held_by": null},
    {"category": "general", "text": "Valdren's economy depends heavily on mining iron ore from deposits found in the eastern slopes of the Greenwall, as well as livestock grazing on the high alpine meadows that remain above the tree line.", "held_by": null},
    {"category": "general", "text": "The kingdom has a single major trade route running north to south through its central valley, connecting its capital in the south to a coastal port on the Greensea, which allows limited maritime commerce with southern powers.", "held_by": null},
    {"category": "general", "text": "Valdren's ruling monarch, currently unnamed in official Moscavian records, governs from a fortified capital in the southern lowlands, far from the border with Moscavia.", "held_by": null}
  ],
  "names": [
    {"name": "Greenwall Mountains", "kind": "place", "tag": "mountains", "in": null, "aka": []},
    {"name": "Greensea", "kind": "place", "tag": "sea", "in": null, "aka": []},
    {"name": "Moscavia", "kind": "place", "tag": "nation", "in": null, "aka": [{"name": "Tsardom of Moscavia", "tag": "proper", "everyday": false}]},
    {"name": "Frostwing Host", "kind": "lore", "tag": "military", "in": null, "aka": [{"name": "Frostwing", "tag": "common", "everyday": true}]}
  ],
  "in": [
    {"entry": "Tsardom of Moscavia", "role": "western neighbor"}
  ],
  "file_into": [],
  "elsewhere": [
    {"entry": "Frostwing Host", "text": "The Frostwing Host monitors the western mountain passes of the Greenwall as part of its border deployment, conducting nighttime patrols from watchtowers positioned at key pass elevations to detect any Valdrenese military movement.", "held_by": null},
    {"entry": "Tsardom of Moscavia", "text": "The Night Court considers Valdren a secondary strategic concern compared to the northern glacier approaches and eastern marshland corridors, though it allocates sufficient Frostwing resources to monitor the western border for signs of border skirmishes or smuggling.", "held_by": null}
  ]
}

{ "name": "Church of the White Dawn",
  "aka": [
    {
      "name": "Belaya Zorya",
      "tag": "common",
      "everyday": true
    }
  ],
  "tag": "institution, doctrine",
  "facts": [
    {
      "category": "general",
      "text": "The Church of the White Dawn is the state church of the Tsardom of Moscavia, established as the dominant religious institution of the realm following the Blinding of 994.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Its seat is the Cathedral of the White Dawn in Velikoye, the first major stone structure in the capital to be retrofitted with roosting perches and talon-gripping ledges to accommodate Owl-folk worshippers and clergy.",
      "since": null,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Church teaches that the Blinding was not a catastrophe but a divine illumination — a revelation sent by the White Dawn to transform and elevate the people of Moscavia into vessels of nocturnal wisdom.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Its clergy consists entirely of Owl-folk, drawn predominantly from Snowy Owl-folk bloodlines, and organized into a hierarchy of deacons, priests, bishops, and the Supreme Prelate who serves as the Church's spiritual head.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Church holds that the natural nocturnal rhythms of the Owl-folk reflect the divine order intended for all creation, and that the long northern nights are sacred periods of communion between the faithful and the White Dawn.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Its doctrine rejects the notion that the Blinding was an act of punishment or random magic, instead asserting that every transformed soul was individually chosen and blessed by the White Dawn to serve as stewards of the frozen north.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Church maintains a network of parish churches and chapels across Moscavia, each retrofitted with roosting accommodations, and conducts its primary services at night to align with the nocturnal nature of its congregants.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Winter Solstice Vigil is the Church's most sacred observance, marking the longest night of the year as the moment when the White Dawn burns brightest in the spiritual realm, and the faithful gather in unbroken vigil through three days of prayer and ceremony.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "The Church's liturgy incorporates runic inscriptions carved into stone and bone, believed to channel the White Dawn's light into physical blessings, and its rune-practitioners work closely with the Order of the Talon-Scribe.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
      "text": "Human converts who were not transformed during the Blinding are permitted to worship in Church chapels but may not hold clerical rank, a policy justified by the doctrine of unbroken bloodline sanctity.",
      "since": 994,
      "held_by": null
    },
    {
      "category": "general",
