    {
      "entry": "Tsardom of Moscavia",
      "text": "The Tsardom of Moscavia is governed from Velikoye by a Tsar who rules with the counsel of the Night Court, which conducts its sessions after sundown to accommodate the nocturnal nature of the ruling Owl-folk class.",
      "held_by": null
    },
    {
      "entry": "Tsar Dmitry IV",
      "text": "Tsar Dmitry IV presides over the Night Court from his palace in Velikoye, where he holds ultimate authority over all matters of state and personally sets the agenda for each session.",
      "held_by": null
    },
    {
      "entry": "Velikoye",
      "text": "Velikoye serves as the seat of the Night Court, whose sessions are held in the Great Hall of the Tsar's Palace within the city's fortified inner quarter.",
      "held_by": null
    },
    {
      "entry": "The Talon-Scribe Order",
      "text": "The Talon-Scribe Order maintains a permanent presence within the Night Court, with registered scribes stationed in the Great Hall to record all proceedings and carve official decrees onto stone tablets for public display.",
      "held_by": null
    },
    {
      "entry": "Plumage Signaling",
      "text": "Plumage Signaling is used extensively within the Night Court during debates and deliberations, where advisors communicate agreement, disagreement, and urgency through subtle shifts in their feather coloration and arrangement.",
      "held_by": null
    },
    {
      "entry": "The Blinding",
      "text": "The Blinding of 994 directly precipitated the establishment of the Night Court, as the sudden transformation of millions of humans into Owl-folk necessitated a governing body that could operate after sundown.",
      "held_by": null
    },
    {
      "entry": "Moscavian Owl-folk",
      "text": "The ruling class of the Night Court is composed almost entirely of Snowy Owl-folk, whose unbroken Moscavian bloodlines grant them social prestige and dominance within the realm's civic and religious institutions.",
      "held_by": null
    },
    {
      "entry": "The Frostwing Host",
      "text": "The Frostwing Host provides military representation to the Night Court through senior commanders who report directly to the Tsar on border security, patrol effectiveness, and troop readiness.",
      "held_by": null
    }
  ]
}

